from typing import List, Union
import numpy as np
import scipy.fft
def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if data is None or len(data) == 0:
        return {"mode": np.array([]), "count": np.array([])}

    # Handle invalid repetitions
    if repetitions < 0:
        return {"mode": np.array([]), "count": np.array([])}

    arr = np.array(data)

    # Compute mode(s) and count(s) without explicitly expanding the repeated data
    values, counts = np.unique(arr, return_counts=True)
    counts = counts * repetitions

    max_count = counts.max() if counts.size else 0
    mask = counts == max_count

    modes = values[mask]
    mode_counts = counts[mask]

    # Ensure ascending order of modes
    order = np.argsort(modes)
    modes = modes[order]
    mode_counts = mode_counts[order]

    # Compute FFT of the repeated data (not returned, but calculated as requested)
    try:
        if np.issubdtype(arr.dtype, np.number):
            repeated = np.tile(arr, repetitions)
            _fft = scipy.fft.fft(repeated)
        else:
            _fft = None
    except Exception:
        _fft = None

    return {"mode": np.array(modes), "count": np.array(mode_counts)}
