from collections import Counter
def task_func(input_str):
    if input_str is None:
        return {}


    cleaned = re.sub(r"[^\w]+", "", str(input_str))
    cleaned = cleaned.strip().lower()

    tokens = word_tokenize(cleaned)
    counts = Counter(tokens)
    return dict(counts)
