import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose
def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    idx = pd.date_range(start=start_date, periods=periods, freq=freq)


    if freq.upper().endswith('M'):
        seasonal_period = 12
    elif freq.upper().endswith('Q'):
        seasonal_period = 4
    elif freq.upper().endswith('W'):
        seasonal_period = 52
    elif freq.upper().endswith('D'):
        seasonal_period = 7
    else:
        seasonal_period = 12

    rng = np.random.default_rng(42)


    trend = np.linspace(200.0, 260.0, periods)
    season = 1.0 + 0.15 * np.sin(2 * np.pi * np.arange(periods) / seasonal_period)

    if model == 'multiplicative':
        noise = rng.normal(0.0, 3.0, periods)
        sales = trend * season + noise
    else:
        noise = rng.normal(0.0, 8.0, periods)
        sales = trend + 25.0 * np.sin(2 * np.pi * np.arange(periods) / seasonal_period) + noise

    sales_series = pd.Series(sales, index=idx, name="sales")



    period_for_decomp = (12 if not freq.upper().endswith('M') else 4 * 12) if model == 'multiplicative' else seasonal_period

    try:
        decomp = seasonal_decompose(sales_series, model=model, period=period_for_decomp)
    except ValueError as e:
        return {"error": str(e)}

    return {
        "trend": decomp.trend,
        "seasonal": decomp.seasonal,
        "residual": decomp.resid
    }
```

