        raise ValueError("n_tasks cannot be negative.")
    if n_tasks < 0:
        raise ValueError("n_tasks is negative.")

    rng = random.Random(seed)

    tasks = list(task_list) if task_list is not None else []
    employees_list = list(employees) if employees is not None else []

    if not employees_list and n_tasks > 0:
        raise ValueError("Employees list cannot be empty when assigning tasks.")


    if n_tasks <= len(tasks):
        chosen_tasks = rng.sample(tasks, n_tasks)
    else:
        chosen_tasks = tasks[:]
        if tasks:
            chosen_tasks += [rng.choice(tasks) for _ in range(n_tasks - len(tasks))]
        else:

            return pd.DataFrame(columns=["Task Name", "Assigned To", "Due Date"])

