    rows = []
    for t in chosen_tasks:
        task_name = str(t).replace(" ", "_")
        assigned_to = rng.choice(employees_list)
        rows.append(
            {
                "Task Name": task_name,
                "Assigned To": assigned_to,
                "Due Date": due_date,
            }
        )

    return pd.DataFrame(rows, columns=["Task Name", "Assigned To", "Due Date"])
