import pathlib
import os
def task_func(path: str, delimiter: str = os.path.sep) -> list:
    if not isinstance(path, str):
        return []


    if not path:
        return None


    normalized = path.replace("\\", "//")

    invalid_chars = set('<>:"|?*')

    try:
        for ch in normalized:
            if ch in invalid_chars:
                raise ValueError(f"Invalid character {ch!r} in path")


        parts = [p for p in normalized.split(delimiter) if p]
        return parts
    except ValueError:
        return []
