import os
import re
from pathlib import Path
def task_func(dir_path: str, predicates: list) -> dict:
    p = Path(dir_path)
    if not p.exists() or not p.is_dir():
        raise FileNotFoundError(f"{dir_path} does not exist or is not a directory")

    if not isinstance(predicates, list):
        raise ValueError("Predicates must be provided as a list")

    normalized = []
    for pred in predicates:
        if callable(pred):
            normalized.append(pred)
        elif isinstance(pred, re.Pattern):
            normalized.append(pred)
        elif isinstance(pred, str) and pred:
            try:
                normalized.append(re.compile(pred))
            except re.error:
                # ignore invalid regex patterns
                continue
        else:
            # ignore unknown predicate types
            continue

    # Deduplicate predicates
    unique = []
    seen = set()
    for pred in normalized:
        if pred in seen:
            continue
        seen.add(pred)
        unique.append(pred)

    if not unique:
        raise ValueError("No valid predicates provided")

    results = {}
    with os.scandir(dir_path) as it:
        for entry in it:
            item_path = os.path.join(dir_path, entry.name)
            checks = []
            for pred in unique:
                if callable(pred):
                    checks.append(bool(pred(item_path)))
                else:
                    checks.append(bool(pred.search(item_path)))
            results[entry.name] = checks

    return results
