    if root.tag != "items":
        raise ValueError("XML structure does not match expected format.")

    item_elems = root.findall("item")
    if not item_elems:
        raise ValueError("XML structure does not match expected format.")

    rows = []
    for item in item_elems:
        row = {}
        for child in item.getchildren():
            if isinstance(child.tag, str):
                text = child.text.strip() if child.text is not None else ""
                row[child.tag] = text
        rows.append(row)

    return pd.DataFrame(rows)
