import json
import requests
import chardet

# Constants
API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()  # Raise an exception for HTTP errors

        content = response.content

        if not content:
            return {}

        if from_encoding is None:
            result = chardet.detect(content)
            if 'encoding' in result and result['confidence'] > 0.8:
                from_encoding = result['encoding']
            else:
                raise ValueError("Unable to detect encoding for non-empty content")

        decoded_content = content.decode(from_encoding, errors='ignore')
        encoded_content = decoded_content.encode(to_encoding)

        parsed_data = json.loads(encoded_content.decode(to_encoding))
        return parsed_data

    except requests.exceptions.RequestException as e:
        print(f"HTTP Request failed: {e}")
        return {}
    except ValueError as ve:
        print(ve)
        return {}

# Example usage:
