import ssl
import os
import hashlib
def task_func(client_socket, cert_file, key_file, buffer_size=1024):
    ssl_sock = None
    try:
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=cert_file, keyfile=key_file)

        ssl_sock = context.wrap_socket(client_socket, server_side=True)


        raw = ssl_sock.recv(buffer_size)
        if not raw:
            return "Error: No file path received"

        file_path = raw.decode("utf-8").strip()

        if not os.path.exists(file_path):

            response = sha.hexdigest()
            try:
                ssl_sock.sendall(response.encode("utf-8"))
            except Exception:
                pass
            return response

        sha = hashlib.sha256()

        with open(file_path, "r") as f:
            while True:
                chunk = f.read(8192)
                if not chunk:
                    break
                sha.update(chunk.encode("utf-8"))

        digest = sha.hexdigest()
        try:
            ssl_sock.sendall(digest.encode("utf-8"))
        except Exception:
            pass
        return digest

    except Exception as e:
        return f"Error: {e}"
    finally:
        if ssl_sock:

            ssl_sock.close
