```python
import pandas as pd
import itertools
import random
def task_func(colors, states):
    if not colors or not states:
        return pd.DataFrame()


    combos = [f"{c}:{s}" for c, s in itertools.product(colors, states)]
    random.seed(42)
    random.shuffle(combos)


    ncols = max(len(colors), len(states))


    cols = [[] for _ in range(ncols)]
    for i, val in enumerate(combos):
        cols[i % ncols].append(val)


    data = {f"Color:State {i+1}": cols[i] for i in range(ncols)}
    return pd.DataFrame(data)
