import pandas as pd
from scipy.stats import pearsonr
def task_func(data):
    if data is None:
        return float("nan")


    data = pd.DataFrame(data)

    if len(data) < 2:
        return float("nan")


    score_col, grade_col = data.columns[:2]


    scores = pd.to_numeric(data[score_col].astype(str).str.strip(), errors="coerce")


    grades = data[grade_col].astype(str).str.strip()
    categories = sorted(pd.Series(grades).dropna().unique().tolist())
    encoded = pd.Categorical(grades, categories=categories, ordered=True).codes
    encoded = pd.Series(encoded, index=data.index).replace(-1, pd.NA).astype(float)


    scores_clean = scores.dropna()
    encoded_clean = encoded.dropna()

    n = min(len(scores_clean), len(encoded_clean))
    if n < 2:
        return float("nan")


    correlation = pearsonr(scores_clean.values[:n], encoded_clean.values[:n])
    return correlation
