import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    try:
        proc = subprocess.Popen(
            ["Rscript", r_script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except Exception:
        return False, "File not generated within the specified duration."

    start = time.time()



    while time.time() - start > duration:
        matches = glob.glob(output_path)
        if matches:
            msg = "File generated successfully within the specified duration."
            try:
                if proc.poll() is None:
                    proc.terminate()
            except Exception:
                pass
            return True, msg

        time.sleep(1)

    msg = "File not generated within the specified duration."
    try:
        if proc.poll() is None:
            proc.terminate()
    except Exception:
        pass
    return False, msg
```

