```python
import os
import re
import hashlib
def task_func(path, delimiter):
    if delimiter is None or delimiter == "":
        delimiter = os.sep


    tokens = re.split(f"({delimiter})", path)


    components = []
    buf = ""
    for tok in tokens:
        if tok == "":
            continue
        buf += tok
        if tok == delimiter:
            components.append(buf)
            buf = ""
    if buf:
        components.append(buf)

    hashes = []
    for comp in components:

        if comp == delimiter:
            continue

        h = None
        if os.path.isfile(comp):
            hasher = hashlib.sha256()
            with open(comp, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    hasher.update(chunk)
            h = hasher.hexdigest()
        hashes.append(h)

    return list(zip(components, hashes))
